$(document).ready(function() {
    console.log('jQuery v' + $.fn.jquery + ' loaded successfully');

    // Input Field Focus Effects
    $('.input-field').on('focus', function() {
        $(this).animate({ opacity: 1 }, 300);
        $(this).next('.input-line').css({
            background: 'rgba(255, 255, 255, 0.5)',
            transform: 'scaleX(1.05)'
        });
    });

    // Login Button Click
    $('#loginBtn').on('click', function() {
        var email = $('#email').val();
        var password = $('#password').val();
        
        if (email === '' || password === '') {
            // Show error with shake animation
            $(this).addClass('shake');
            // ... validation logic ...
        } else {
            // Login process with loading state
            $(this).text('Loading...').prop('disabled', true);
            // ... success logic ...
        }
    });

    // Create Account Link
    $('#createAccountLink').on('click', function(e) {
        e.preventDefault();
        alert('Redirecting to Create Account page...');
    });

    // Forgot Password Link
    $('#forgotPasswordLink').on('click', function(e) {
        e.preventDefault();
        var userEmail = prompt('Enter your email address to reset password:');
        // ... password reset logic ...
    });

    // All interactive features included in the file
});


